library(tidyverse)
library(ggrastr)
library(ggrepel)
library(patchwork)

argv=commandArgs(T)
nb_file=argv[1]
target_genes=argv[2]
out_name=argv[3]
flip_direction=as.logical(argv[4])
limit=as.numeric(argv[5])


if(FALSE){
	nb_file="/path/to/Primary.B.pQTL.ADT.genotype.nb.result.tsv.gz"
	target_genes="CD40"
	out_name="Primary.B.pQTL.ADT"
}

#flip beta to make 'T' as a assessed allele
nb_df<-read_tsv(nb_file)
if(flip_direction==TRUE){
nb_df<-mutate(nb_df,BETA=(-BETA))
}


target_genes<-str_split(target_genes,",")%>%unlist()

#make volcano plot for LRT P-values
make_volcano<-function(df,p_val_col,gene_list,FDR_THR){
	tmp<-dplyr::select(df,all_of(c("Gene","BETA",p_val_col)))
	colnames(tmp)<-c("Gene","BETA","pvalue")
	tmp$FDR<-p.adjust(tmp$pvalue, method="BH")
	val1<-filter(tmp,FDR<FDR_THR)%>%pull(pvalue)%>%max()
	val2<-filter(tmp,FDR>=FDR_THR)%>%pull(pvalue)%>%min()
	fdr_thr<-(log10(val1)+log10(val2))*(-0.5)

	tmp<-tmp%>%mutate(highlight=ifelse(Gene %in% gene_list,TRUE,FALSE))%>%
	arrange(pvalue)%>%mutate(category=case_when(
		FDR<FDR_THR&BETA>0 ~ "pos",
		FDR<FDR_THR&BETA<0 ~ "neg",
		TRUE~"others"
	))

	#also annotate top 10 genes
	top_genes<-head(tmp,10)%>%pull(Gene)

	pos_cnt<-filter(tmp,category=="pos")%>%nrow()
	neg_cnt<-filter(tmp,category=="neg")%>%nrow()

	p<-ggplot(tmp,aes(x=BETA,
	y=ifelse(-log10(pvalue)>limit,limit,-log10(pvalue))))+
	geom_point_rast(data=subset(tmp,highlight==FALSE),alpha=0.8,size=1,aes(color=category))+
	geom_point(data=subset(tmp,highlight==TRUE),alpha=0.8,size=2,color="red")+
	geom_text_repel(data=subset(tmp,Gene %in% top_genes & highlight==FALSE),aes(label=Gene,color=category),alpha=0.8,size=2,color="black")+
	geom_text_repel(data=subset(tmp,highlight==TRUE),aes(label=Gene),alpha=0.8,size=2,color="#FF7F0E")+
	theme_test()+
	theme(
	axis.text.x = element_text(size = 10),
	axis.text.y = element_text(size = 10),
	aspect.ratio=1/1)+
	xlab("Effect size")+ylab("-log10(P)")+
	geom_hline(yintercept=fdr_thr,color="black")+
	geom_vline(xintercept=0,color="black",linetype="dashed")+
	scale_color_manual(values=c("pos"="#D62728","neg"="#1F77B4","others"="#555555"))+
	  geom_text(x = -Inf, y = Inf,
              label = neg_cnt,
              hjust = -0.1, vjust = 1.5, size = 3, color = "#1F77B4")+
    geom_text(x = Inf, y = Inf,
              label = pos_cnt,
              hjust = 1.1, vjust = 1.5, size = 3, color = "#D62728")+ylim(c(0,limit*1.01))

	return(list(plot = p, df = tmp))

}


obj1<-make_volcano(nb_df,"LRT_P",target_genes,0.05)
obj2<-make_volcano(nb_df,"LRT_P",target_genes,0.1)

ggsave(str_c(out_name,".LRT.P.volcano.FDR.0.05.pdf"),obj1[["plot"]],width=4,height=4)
ggsave(str_c(out_name,".LRT.P.volcano.FDR.0.10.pdf"),obj2[["plot"]],width=4,height=4)

obj1[["df"]]%>%write_tsv(str_c(out_name,".LRT.P.volcano.FDR.05.tsv.gz"))
obj2[["df"]]%>%write_tsv(str_c(out_name,".LRT.P.volcano.FDR.10.tsv.gz"))
